CREATE TABLE credit_types (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, instructions TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));

CREATE TABLE event_content (id INTEGER PRIMARY KEY, draft TEXT NOT NULL, published TEXT, revision INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);

CREATE TABLE event_settings (id INTEGER PRIMARY KEY CHECK(id=1), policy TEXT NOT NULL CHECK(portal_json_valid(policy)), active INTEGER NOT NULL DEFAULT 0 CHECK(active IN (0,1)), version INTEGER NOT NULL DEFAULT 1);

CREATE TABLE private_venue (id INTEGER PRIMARY KEY, draft TEXT NOT NULL, published TEXT, revision INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);

CREATE TABLE registrations (email CITEXT PRIMARY KEY, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','cancelled')), luma_confirmed INTEGER NOT NULL DEFAULT 0 CHECK(luma_confirmed IN (0,1)));

CREATE TABLE request_buckets (actor_id TEXT NOT NULL, "window" INTEGER NOT NULL, count INTEGER NOT NULL CHECK(count<=120), PRIMARY KEY(actor_id,"window"));

CREATE TABLE scoring_revision (id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL DEFAULT 0);

CREATE TABLE users (id TEXT PRIMARY KEY, email CITEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'participant' CHECK(role IN ('participant','admin','judge')), created_at TEXT NOT NULL);

CREATE TABLE write_guards (token TEXT PRIMARY KEY, valid INTEGER NOT NULL CHECK(valid=1));

CREATE TABLE audit_logs (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, entity_id TEXT NOT NULL, detail TEXT NOT NULL CHECK(portal_json_valid(detail)), reason TEXT NOT NULL, created_at TEXT NOT NULL);

CREATE TABLE "automatic_absences" (
	"user_id" text PRIMARY KEY NOT NULL,
	"reconciled_at" text NOT NULL,
	"cutoff" text NOT NULL,
	FOREIGN KEY ("user_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action
);

CREATE TABLE check_ins (user_id TEXT PRIMARY KEY REFERENCES users(id), actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);

CREATE TABLE credit_batches (
 id TEXT PRIMARY KEY,
 digest TEXT NOT NULL,
 created_by TEXT NOT NULL REFERENCES users(id),
 created_at TEXT NOT NULL,
 deleted_at TEXT,
 UNIQUE(created_by,digest)
);

CREATE TABLE credit_inventory (id TEXT PRIMARY KEY, type_id TEXT NOT NULL REFERENCES credit_types(id), ciphertext TEXT NOT NULL, fingerprint TEXT NOT NULL, created_at TEXT NOT NULL, voucher_value text, UNIQUE(type_id,fingerprint), rowid INTEGER GENERATED ALWAYS AS IDENTITY UNIQUE);

CREATE TABLE "engagement_controls" (
	"id" integer PRIMARY KEY NOT NULL,
	"voting_paused" integer DEFAULT 0 NOT NULL,
	"feedback_paused" integer DEFAULT 0 NOT NULL,
	"version" integer DEFAULT 1 NOT NULL,
	"actor_id" text NOT NULL,
	"updated_at" text NOT NULL,
	FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action,
	CONSTRAINT "engagement_singleton" CHECK("engagement_controls"."id"=1),
	CONSTRAINT "engagement_vote_flag" CHECK("engagement_controls"."voting_paused" IN (0,1)),
	CONSTRAINT "engagement_feedback_flag" CHECK("engagement_controls"."feedback_paused" IN (0,1))
);

CREATE TABLE event_content_history (id TEXT PRIMARY KEY, scope TEXT NOT NULL CHECK(scope IN ('public','private')), revision INTEGER NOT NULL, snapshot TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);

CREATE TABLE "event_policy_history" (
	"version" integer PRIMARY KEY NOT NULL,
	"policy" text NOT NULL,
	"actor_id" text NOT NULL,
	"created_at" text NOT NULL,
	"reason" text NOT NULL,
	FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action
);

CREATE TABLE import_previews (actor_id TEXT NOT NULL REFERENCES users(id), digest TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(actor_id,digest));

CREATE TABLE "luma_roster" (
	"email" text PRIMARY KEY NOT NULL,
	"imported_by" text NOT NULL,
	"imported_at" text NOT NULL,
	FOREIGN KEY ("imported_by") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action
);

CREATE TABLE "manual_checkins" (
	"user_id" text NOT NULL,
	"verified_email" text NOT NULL,
	"actor_id" text NOT NULL,
	"created_at" text NOT NULL,
	PRIMARY KEY("user_id", "verified_email"),
	FOREIGN KEY ("user_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action
);

CREATE TABLE participant_profiles (user_id TEXT PRIMARY KEY REFERENCES users(id), display_name TEXT NOT NULL, skills TEXT NOT NULL DEFAULT '', completed_at TEXT NOT NULL, gender_confirmed INTEGER NOT NULL DEFAULT 0);

CREATE TABLE "participant_status_overrides" (
	"user_id" text PRIMARY KEY NOT NULL,
	"status" text NOT NULL,
	"reason" text NOT NULL,
	"actor_id" text NOT NULL,
	"updated_at" text NOT NULL,
	FOREIGN KEY ("user_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action,
	CONSTRAINT "person_override_status" CHECK("participant_status_overrides"."status" IN ('Registered','Going','Checked in','Absent'))
);

CREATE TABLE portal_roles (user_id TEXT PRIMARY KEY REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('participant','volunteer','mentor','judge','admin')), granted_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL);

CREATE TABLE private_venue_managers (user_id TEXT PRIMARY KEY REFERENCES users(id), granted_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL);

CREATE TABLE "profile_details" (
	"user_id" text PRIMARY KEY NOT NULL,
	"phone" text DEFAULT '' NOT NULL,
	"best_description" text DEFAULT '' NOT NULL,
	"organization" text DEFAULT '' NOT NULL,
	"openai_org_id" text DEFAULT '' NOT NULL, "avatar_color" text DEFAULT 'blue' NOT NULL, "avatar_expression" text DEFAULT 'squeezed' NOT NULL,
	FOREIGN KEY ("user_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action
);

CREATE TABLE "profile_photos" (
	"user_id" text PRIMARY KEY NOT NULL,
	"png" text NOT NULL,
	"updated_at" text NOT NULL,
	FOREIGN KEY ("user_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action
);

CREATE TABLE profiles (user_id TEXT PRIMARY KEY REFERENCES users(id), bio TEXT NOT NULL DEFAULT '', socials TEXT NOT NULL DEFAULT '[]' CHECK(portal_json_valid(socials)), gender TEXT NOT NULL DEFAULT 'prefer-not-to-say' CHECK(gender IN ('woman','man','non-binary','self-described','prefer-not-to-say')), gender_description TEXT NOT NULL DEFAULT '', public INTEGER NOT NULL DEFAULT 0 CHECK(public IN (0,1)));

CREATE TABLE "record_removals" (
	"kind" text NOT NULL,
	"target_id" text NOT NULL,
	"active" integer DEFAULT 1 NOT NULL,
	"reason" text NOT NULL,
	"actor_id" text NOT NULL,
	"updated_at" text NOT NULL,
	"snapshot" text DEFAULT '{}' NOT NULL,
	PRIMARY KEY("kind", "target_id"),
	FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action,
	CONSTRAINT "removal_kind" CHECK("record_removals"."kind" IN ('participant','team','project','submission')),
	CONSTRAINT "removal_active" CHECK("record_removals"."active" IN (0,1))
);

CREATE TABLE "registration_absences" (
	"email" CITEXT PRIMARY KEY NOT NULL,
	"reconciled_at" text NOT NULL,
	"cutoff" text NOT NULL,
	FOREIGN KEY ("email") REFERENCES "registrations"("email") ON UPDATE no action ON DELETE no action
);

CREATE TABLE result_snapshots (id TEXT PRIMARY KEY, policy_version INTEGER NOT NULL, source_revision INTEGER NOT NULL, payload TEXT NOT NULL CHECK(portal_json_valid(payload)), created_at TEXT NOT NULL, frozen_by TEXT NOT NULL REFERENCES users(id));

CREATE TABLE "score_releases" (
	"id" text PRIMARY KEY NOT NULL,
	"stage" text NOT NULL,
	"source_id" text NOT NULL,
	"payload" text NOT NULL,
	"criteria" text,
	"created_at" text NOT NULL,
	"actor_id" text NOT NULL,
	FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action,
	CONSTRAINT "score_release_stage" CHECK("score_releases"."stage" IN ('ai','final')),
	CONSTRAINT "score_release_json" CHECK(portal_json_valid("score_releases"."payload"))
);

CREATE TABLE teams (id TEXT PRIMARY KEY, name CITEXT NOT NULL UNIQUE, leader_id TEXT NOT NULL REFERENCES users(id), bio TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);

CREATE TABLE credit_allocations (inventory_id TEXT PRIMARY KEY REFERENCES credit_inventory(id), type_id TEXT NOT NULL REFERENCES credit_types(id), user_id TEXT NOT NULL REFERENCES users(id), assigned_at TEXT NOT NULL, "recipient_email" text, UNIQUE(type_id,user_id));

CREATE TABLE credit_batch_columns (
 batch_id TEXT NOT NULL REFERENCES credit_batches(id),
 type_id TEXT NOT NULL UNIQUE REFERENCES credit_types(id),
 column_key TEXT NOT NULL,
 source_heading TEXT NOT NULL,
 PRIMARY KEY(batch_id,column_key)
);

CREATE TABLE feedback (author_id TEXT NOT NULL REFERENCES users(id), team_id TEXT NOT NULL REFERENCES teams(id), text TEXT NOT NULL, valid INTEGER NOT NULL DEFAULT 1 CHECK(valid IN (0,1)), moderation_reason TEXT, updated_at TEXT NOT NULL, PRIMARY KEY(author_id,team_id));

CREATE TABLE human_scores (judge_id TEXT NOT NULL REFERENCES users(id), team_id TEXT NOT NULL REFERENCES teams(id), rating DOUBLE PRECISION NOT NULL CHECK(rating BETWEEN 0 AND 10), notes TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(judge_id,team_id));

CREATE TABLE idea_revisions (id TEXT PRIMARY KEY, team_id TEXT NOT NULL REFERENCES teams(id), snapshot TEXT NOT NULL CHECK(portal_json_valid(snapshot)), created_at TEXT NOT NULL);

CREATE TABLE ideas (team_id TEXT PRIMARY KEY REFERENCES teams(id), title TEXT NOT NULL, core TEXT NOT NULL, description TEXT NOT NULL, hash TEXT NOT NULL, updated_at TEXT NOT NULL);

CREATE TABLE judge_assignments (judge_id TEXT NOT NULL REFERENCES users(id), team_id TEXT NOT NULL REFERENCES teams(id), PRIMARY KEY(judge_id,team_id));

CREATE TABLE memberships (user_id TEXT PRIMARY KEY REFERENCES users(id), team_id TEXT NOT NULL REFERENCES teams(id), joined_at TEXT NOT NULL);

CREATE TABLE result_publication (id INTEGER PRIMARY KEY CHECK(id=1), snapshot_id TEXT NOT NULL REFERENCES result_snapshots(id), published_at TEXT NOT NULL);

CREATE TABLE "roster_prefills" (
	"email" text PRIMARY KEY NOT NULL,
	"payload" text NOT NULL,
	"imported_at" text NOT NULL,
	FOREIGN KEY ("email") REFERENCES "luma_roster"("email") ON UPDATE no action ON DELETE no action
);

CREATE TABLE submission_versions (id TEXT PRIMARY KEY, team_id TEXT NOT NULL REFERENCES teams(id), attempt INTEGER NOT NULL CHECK(attempt BETWEEN 1 AND 3), payload TEXT NOT NULL CHECK(portal_json_valid(payload)), created_at TEXT NOT NULL, UNIQUE(team_id,attempt));

CREATE TABLE team_actions (id TEXT PRIMARY KEY, team_id TEXT NOT NULL REFERENCES teams(id), user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('invite','request')), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined')), created_at TEXT NOT NULL, UNIQUE(team_id,user_id,kind));

CREATE TABLE "team_locks" (
	"team_id" text PRIMARY KEY NOT NULL,
	"locked_by" text NOT NULL,
	"locked_at" text NOT NULL,
	FOREIGN KEY ("team_id") REFERENCES "teams"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("locked_by") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action
);

CREATE TABLE "team_status_overrides" (
	"team_id" text PRIMARY KEY NOT NULL,
	"status" text NOT NULL,
	"reason" text NOT NULL,
	"rule_reference" text,
	"evidence" text,
	"actor_id" text NOT NULL,
	"updated_at" text NOT NULL,
	FOREIGN KEY ("team_id") REFERENCES "teams"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action,
	CONSTRAINT "team_override_status" CHECK("team_status_overrides"."status" IN ('Forming','Locked','Not submitted','Submitted'))
);

CREATE TABLE team_styles (team_id TEXT PRIMARY KEY REFERENCES teams(id), avatar TEXT NOT NULL DEFAULT 'orbit', palette TEXT NOT NULL DEFAULT 'forest', "color_key" text);

CREATE TABLE tie_resolutions(group_hash TEXT NOT NULL,team_id TEXT NOT NULL REFERENCES teams(id),ordinal INTEGER NOT NULL CHECK(ordinal>0),PRIMARY KEY(group_hash,team_id),UNIQUE(group_hash,ordinal));

CREATE TABLE votes (voter_id TEXT NOT NULL REFERENCES users(id), team_id TEXT NOT NULL REFERENCES teams(id), created_at TEXT NOT NULL, PRIMARY KEY(voter_id,team_id));

CREATE TABLE astra_jobs (id TEXT PRIMARY KEY, version_id TEXT NOT NULL UNIQUE REFERENCES submission_versions(id), state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','running','needs_review','failed_retryable','finalized')), attempts INTEGER NOT NULL DEFAULT 0, report TEXT CHECK(report IS NULL OR portal_json_valid(report)), error TEXT, updated_at TEXT NOT NULL);

CREATE TABLE projects (id TEXT PRIMARY KEY, team_id TEXT NOT NULL UNIQUE REFERENCES teams(id), slug TEXT NOT NULL UNIQUE, draft TEXT NOT NULL DEFAULT '{}' CHECK(portal_json_valid(draft)), revision INTEGER NOT NULL DEFAULT 1, published_version_id TEXT REFERENCES submission_versions(id), updated_at TEXT NOT NULL);

CREATE TABLE reviews (team_id TEXT PRIMARY KEY REFERENCES teams(id), version_id TEXT NOT NULL REFERENCES submission_versions(id), eligibility TEXT NOT NULL CHECK(eligibility IN ('eligible','ineligible','needs_review')), astra DOUBLE PRECISION CHECK(astra BETWEEN 0 AND 30), codex DOUBLE PRECISION CHECK(codex BETWEEN 0 AND 5), diversity DOUBLE PRECISION CHECK(diversity BETWEEN 0 AND 10), false_claims INTEGER NOT NULL DEFAULT 0 CHECK(false_claims BETWEEN 0 AND 2), evidence TEXT NOT NULL, reviewer_id TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL);

CREATE TABLE "eligibility_history" (
	"id" text PRIMARY KEY NOT NULL,
	"project_id" text NOT NULL,
	"version_id" text NOT NULL,
	"status" text NOT NULL,
	"reason" text NOT NULL,
	"evidence" text NOT NULL,
	"actor_id" text NOT NULL,
	"created_at" text NOT NULL,
	FOREIGN KEY ("project_id") REFERENCES "projects"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("version_id") REFERENCES "submission_versions"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action
);

CREATE TABLE evaluation_runs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), version_id TEXT NOT NULL REFERENCES submission_versions(id), config_key TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('queued','running','completed','failed','stale')), report TEXT CHECK(report IS NULL OR portal_json_valid(report)), error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, "score" DOUBLE PRECISION, "provenance" text);

CREATE TABLE project_assignments (project_id TEXT NOT NULL REFERENCES projects(id), user_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('judge','mentor')), PRIMARY KEY(project_id,user_id));

CREATE TABLE project_comments (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), author_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL);

CREATE TABLE "project_commit_receipts" (
	"team_id" text NOT NULL,
	"request_key" text NOT NULL,
	"project_id" text NOT NULL,
	"version_id" text NOT NULL,
	"created_at" text NOT NULL,
	PRIMARY KEY("team_id", "request_key"),
	FOREIGN KEY ("team_id") REFERENCES "teams"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("project_id") REFERENCES "projects"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("version_id") REFERENCES "submission_versions"("id") ON UPDATE no action ON DELETE no action
);

CREATE TABLE project_eligibility (project_id TEXT PRIMARY KEY REFERENCES projects(id), version_id TEXT NOT NULL REFERENCES submission_versions(id), status TEXT NOT NULL CHECK(status IN ('eligible','ineligible','needs_review')), reason TEXT NOT NULL, decided_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL);

CREATE TABLE project_review_history (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), version_id TEXT NOT NULL REFERENCES submission_versions(id), author_id TEXT NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('judge','mentor','admin')), body TEXT NOT NULL, rating DOUBLE PRECISION CHECK(rating BETWEEN 0 AND 10), created_at TEXT NOT NULL, rowid INTEGER GENERATED ALWAYS AS IDENTITY UNIQUE);

CREATE TABLE project_upvotes (project_id TEXT NOT NULL REFERENCES projects(id), user_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, PRIMARY KEY(project_id,user_id));

CREATE TABLE "repository_evidence" (
	"id" text PRIMARY KEY NOT NULL,
	"project_id" text NOT NULL,
	"version_id" text NOT NULL,
	"commit_sha" text NOT NULL,
	"status" text NOT NULL,
	"evidence" text NOT NULL,
	"reason" text NOT NULL,
	"actor_id" text NOT NULL,
	"created_at" text NOT NULL,
	FOREIGN KEY ("project_id") REFERENCES "projects"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("version_id") REFERENCES "submission_versions"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action
);

CREATE TABLE "winner_reveals" (
	"release_id" text NOT NULL,
	"position" integer NOT NULL,
	"project_id" text NOT NULL,
	"created_at" text NOT NULL,
	"actor_id" text NOT NULL,
	PRIMARY KEY("release_id", "position"),
	FOREIGN KEY ("release_id") REFERENCES "score_releases"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("project_id") REFERENCES "projects"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("actor_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action,
	CONSTRAINT "winner_position" CHECK("winner_reveals"."position" BETWEEN 1 AND 5)
);

CREATE TABLE "project_feedback_reviews" (
	"id" text PRIMARY KEY NOT NULL,
	"comment_id" text NOT NULL,
	"version_id" text NOT NULL,
	"rule_version" integer NOT NULL,
	"qualified" integer NOT NULL,
	"body_hash" text NOT NULL,
	"reviewer_id" text NOT NULL,
	"reason" text NOT NULL,
	"created_at" text NOT NULL,
	FOREIGN KEY ("comment_id") REFERENCES "project_comments"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("version_id") REFERENCES "submission_versions"("id") ON UPDATE no action ON DELETE no action,
	FOREIGN KEY ("reviewer_id") REFERENCES "users"("id") ON UPDATE no action ON DELETE no action,
	CONSTRAINT "feedback_review_qualified" CHECK("project_feedback_reviews"."qualified" IN (0,1))
, rowid INTEGER GENERATED ALWAYS AS IDENTITY UNIQUE);

