CREATE INDEX audit_time ON audit_logs(created_at);

CREATE UNIQUE INDEX evaluation_single_active ON evaluation_runs(version_id,config_key) WHERE state IN ('queued','running');

CREATE INDEX "feedback_review_lookup" ON "project_feedback_reviews" ("comment_id","version_id","rule_version");

CREATE UNIQUE INDEX legacy_submission_request ON submission_versions(team_id,portal_json_extract(payload,'$._requestKey')) WHERE portal_json_extract(payload,'$._requestKey') IS NOT NULL;

CREATE INDEX memberships_team ON memberships(team_id);

CREATE INDEX project_comments_project ON project_comments(project_id,created_at);

CREATE UNIQUE INDEX "project_commit_receipts_version_id_unique" ON "project_commit_receipts" ("version_id");

CREATE UNIQUE INDEX "score_releases_stage_unique" ON "score_releases" ("stage");

CREATE UNIQUE INDEX "winner_reveals_release_id_project_id_unique" ON "winner_reveals" ("release_id","project_id");
